def write_collections(out_root):
    feat = Path(out_root) / "features"
    feat.mkdir(parents=True, exist_ok=True)
    (feat / "catalog.json").write_text(json.dumps(build_features_catalog(), indent=2) + "\n")
    (feat / "README.md").write_text(_features_catalog_readme())
    (feat / "AGENTS.md").write_text(_agents_md(FEAT_CATALOG_TITLE))
    print(f"wrote {feat}/catalog.json (+ README, AGENTS) — sub-catalog grouping the COG + Zarr collections")
    for year in (2024, 2025):
        d = feat / str(year)
        d.mkdir(parents=True, exist_ok=True)
        (d / "collection.json").write_text(json.dumps(build_collection(year), indent=2) + "\n")
        (d / "README.md").write_text(_readme(year))
        (d / "llms.txt").write_text(_llms(year))
        (d / "AGENTS.md").write_text(_agents_md(cog_title(year)))
        print(f"wrote {d}/collection.json (+ README, llms, AGENTS)")
    z = feat / "zarr"
    z.mkdir(parents=True, exist_ok=True)
    (z / "collection.json").write_text(json.dumps(build_zarr_collection(), indent=2) + "\n")
    (z / "README.md").write_text(_zarr_readme())
    (z / "llms.txt").write_text(_zarr_llms())
    (z / "AGENTS.md").write_text(_agents_md(ZARR_TITLE))
    print(f"wrote {z}/collection.json (+ README, llms, AGENTS) — Zarr mosaic collection")


# ── MGRS browse grid: place labels ───────────────────────────────────

# The per-tile items are browsable as a two-level MGRS tree (UTM zone -> zone+band
# "GZD" -> items). The grid is derivable from the tile id alone, but "35U" means
# nothing to a human, so each node is titled with the countries its tiles fall in.
# That lookup is precomputed once (`places` subcommand, needs duckdb+spatial and
# network) into mgrs_places.json and committed, so neither `collections` nor the
# rails `items` run needs Natural Earth or a spatial join.
PLACES_PATH = Path(__file__).resolve().parent / "mgrs_places.json"
NE_COUNTRIES_URL = ("https://raw.githubusercontent.com/nvkelso/natural-earth-vector/"
                    "master/geojson/ne_50m_admin_0_countries.geojson")
PLACES_TOP_N = 4          # countries named in a title before "(+N more)"


def load_places():
    try:
        return json.loads(PLACES_PATH.read_text())
    except FileNotFoundError:
        print(f"WARNING: {PLACES_PATH.name} missing - grid catalogs get bare MGRS titles "
              f"(run `build_features_items.py places` to generate it)", file=sys.stderr)
        return {"zones": {}, "gzds": {}}


def _fmt_lat(v):
    return f"{abs(v):.0f}°{'N' if v >= 0 else 'S'}"


def _fmt_lon(v):
    return f"{abs(v):.0f}°{'E' if v >= 0 else 'W'}"


def _place_phrase(entry):
    """'Poland, Ukraine, Belarus (+2 more)' - or an offshore lat/lon phrase."""
    if not entry:
        return ""
    names = entry.get("countries") or []
    if names:
        more = entry.get("more") or 0
        return ", ".join(names) + (f" (+{more} more)" if more else "")
    b = entry.get("bbox")
    if not b:
        return ""
    return (f"offshore, {_fmt_lat(b[1])}–{_fmt_lat(b[3])} / "
            f"{_fmt_lon(b[0])}–{_fmt_lon(b[2])}")


def zone_title(zone, places, year=None):
    where = _place_phrase(places.get("zones", {}).get(zone))
    t = f"UTM Zone {int(zone)}" + (f" — {where}" if where else "")
    return f"{t} ({year})" if year else t


def gzd_title(gzd, places, year=None):
    where = _place_phrase(places.get("gzds", {}).get(gzd))
    t = f"Zone {gzd.upper()}" + (f" — {where}" if where else "")
    return f"{t} ({year})" if year else t


def build_places(workdir, top=PLACES_TOP_N):
    """Rebuild mgrs_places.json: for every UTM zone and GZD, the countries its tiles
    actually fall in, ranked by how many tiles each contains (so the label reflects
    where the data is, not which country is biggest). Coastal/offshore tiles match no
    country - a node with none falls back to a lat/lon phrase."""
    import duckdb
    wd = Path(workdir); wd.mkdir(parents=True, exist_ok=True)
    ne = wd / "ne_50m_admin_0_countries.geojson"
    if not ne.exists():
        print(f"downloading Natural Earth 50m admin-0 -> {ne}")
        urllib.request.urlretrieve(NE_COUNTRIES_URL, ne)  # noqa: S310 - trusted host
    con = duckdb.connect()
    con.execute("INSTALL spatial; LOAD spatial; INSTALL httpfs; LOAD httpfs;")
    con.execute(f"create table cty as select NAME as name, geom from ST_Read('{ne}')")
    srcs = ", ".join(f"'{PUB}/features/{y}/items.parquet'" for y in (2024, 2025))
    con.execute(f"""create table t as select distinct
        upper(replace("grid:code", 'MGRS-', '')) as tile,
        bbox.xmin as xmin, bbox.ymin as ymin, bbox.xmax as xmax, bbox.ymax as ymax
        from read_parquet([{srcs}])""")
    n_tiles = con.execute("select count(*) from t").fetchone()[0]
    con.execute("""create table j as select t.tile, cty.name
        from t join cty on ST_Intersects(
            ST_MakeEnvelope(t.xmin, t.ymin, t.xmax, t.ymax), cty.geom)""")
    out = {}
    for key, expr in (("zones", "substr(tile,1,2)"), ("gzds", "lower(substr(tile,1,3))")):
        ranked = con.execute(f"""select {expr} as k, name, count(*) as n
            from j group by 1, 2 order by k, n desc, name""").fetchall()
        bboxes = con.execute(f"""select {expr} as k, min(xmin), min(ymin), max(xmax), max(ymax),
            count(*) from t group by 1 order by 1""").fetchall()
        by_key = {}
        for k, name, n in ranked:
            by_key.setdefault(k, []).append(name)
        out[key] = {}
        for k, xmin, ymin, xmax, ymax, n in bboxes:
            names = by_key.get(k, [])
            e = {"countries": names[:top], "tiles": n,
                 "bbox": [round(v, 4) for v in (xmin, ymin, xmax, ymax)]}
            if len(names) > top:
                e["more"] = len(names) - top
            out[key][k] = e
    PLACES_PATH.write_text(json.dumps(out, indent=1, ensure_ascii=False, sort_keys=True) + "\n")
    named = sum(1 for e in out["gzds"].values() if e["countries"])
    print(f"wrote {PLACES_PATH} from {n_tiles} tiles: {len(out['zones'])} zones, "
          f"{len(out['gzds'])} GZDs ({named} with country names, "
          f"{len(out['gzds']) - named} offshore-only)")


# ── MGRS browse grid: catalogs ───────────────────────────────────────

def grid_catalog_id(year, code):
    return f"{collection_id(year)}-{code.lower()}"


def _grid_desc(year, what, n_items, n_children=None):
    kids = f"{n_children} band cells covering " if n_children else ""
    return (f"{what} of the {year} Sentinel-2 planting/harvest composite tiles — {kids}"
            f"{n_items} tiles, each a STAC item with a `planting` and a `harvest` COG. "
            "Browse structure only: the tiles are also indexed in the collection's "
            f"STAC-GeoParquet ([items.parquet]({PUB}/features/{year}/items.parquet)), which is "
            "the better entry point for querying by geometry, country or date.")


def build_zone_catalog(year, zone, gzds, counts, places):
    """features/<year>/<zone>/catalog.json — one UTM zone, children are its GZD cells."""
    n = sum(counts[g] for g in gzds)
    return {
        "type": "Catalog", "stac_version": "1.1.0", "stac_extensions": [PORTOLAN_EXT],
        "id": grid_catalog_id(year, zone),
        "title": zone_title(zone, places, year),
        "description": _grid_desc(year, f"MGRS UTM zone {int(zone)}", n, len(gzds)),
        "updated": _now(),
        "links": [
            {"rel": "root", "href": "../../../catalog.json", "type": "application/json",
             "title": "Fields of the World — Global"},
            {"rel": "parent", "href": "../collection.json", "type": "application/json",
             "title": cog_title(year)},
            {"rel": "preview", "href": THUMB_HREF, "type": "image/png",
             "title": "Sentinel-2 composite preview"},
            *[{"rel": "child", "href": f"./{g}/catalog.json", "type": "application/json",
               "title": gzd_title(g, places)} for g in gzds],
            {"rel": "describedby", "href": "../README.md", "type": "text/markdown",
             "title": "Human-readable documentation"},
        ],
    }


def build_gzd_catalog(year, gzd, item_ids, places):
    """features/<year>/<zone>/<gzd>/catalog.json — one MGRS grid-zone cell, children are items."""
    return {
        "type": "Catalog", "stac_version": "1.1.0", "stac_extensions": [PORTOLAN_EXT],
        "id": grid_catalog_id(year, gzd),
        "title": gzd_title(gzd, places, year),
        "description": _grid_desc(year, f"MGRS grid zone {gzd.upper()}", len(item_ids)),
        "updated": _now(),
        "links": [
            {"rel": "root", "href": "../../../../catalog.json", "type": "application/json",
             "title": "Fields of the World — Global"},
            {"rel": "parent", "href": "../catalog.json", "type": "application/json",
             "title": zone_title(gzd[:2], places, year)},
            {"rel": "preview", "href": THUMB_HREF, "type": "image/png",
             "title": "Sentinel-2 composite preview"},
            *[{"rel": "item", "href": f"./{i}.json", "type": "application/geo+json",
               "title": f"Tile {i[:5].upper()} ({year})"} for i in item_ids],
            {"rel": "describedby", "href": "../../README.md", "type": "text/markdown",
             "title": "Human-readable documentation"},
        ],
    }


# ── S3-only item + stac-geoparquet generation (run on rails) ──────────────────

def _head_size(url, tries=3):
    """Byte size of a remote asset via HTTP HEAD (Content-Length), or None.

    Retried: a handful of HEADs per thousand fail transiently, and file:size is
    a Portolan MUST — a miss silently drops the field from that asset.
    """
    for attempt in range(tries):
        try:
            req = urllib.request.Request(url, method="HEAD", headers={"User-Agent": "ftw-features"})
            with urllib.request.urlopen(req, timeout=60) as r:  # noqa: S310 - trusted host
                cl = r.headers.get("Content-Length")
                return int(cl) if cl else None
        except Exception:  # noqa: BLE001
            if attempt == tries - 1:
                return None
            time.sleep(2 ** attempt)


def _probe_proj(task):
    """(tile_id, year) -> (tile_id, proj:code, proj:shape, proj:transform), or None.

    Runs in a worker *process*, not a thread: GDAL serialises /vsicurl behind a
    process-global lock, so threads measure ~1.5 s/tile at any pool size (worse
    than the ~1.2 s serial), while processes hit ~90 ms/tile.
    """
    import rasterio
    tile_id, year = task
    cog = f"{COG_BASE}/s2med_harvest/{tile_id}/{year}0101.tif"
    try:
        with rasterio.open(cog) as ds:
            return tile_id, f"EPSG:{ds.crs.to_epsg()}", list(ds.shape), list(ds.transform)[:6]
    except Exception as e:  # noqa: BLE001
        print(f"SKIP {tile_id}: cannot read COG ({e})")
        return None


def _records_from_published_parquet(year, limit=None):
    """Rebuild this year's items from the *published* items.parquet instead of re-reading
    ~45k COG headers and HEADing ~45k assets.

    Everything build_item needs — geometry, bbox, proj:code/shape/transform and each
    asset's file:size — was already resolved by an earlier `items` run and round-trips
    through the STAC-GeoParquet, so a pure metadata change (new links, new tree layout)
    costs one 4.5 MB download instead of ~8 h of network latency on rails. Use the full
    remote passes when the *tiles* change; use this when only the STAC shape changes.
    """
    import duckdb, json as _json
    con = duckdb.connect()
    con.execute("INSTALL spatial; LOAD spatial; INSTALL httpfs; LOAD httpfs; SET TimeZone='UTC';")
    rows = con.execute(f'''SELECT replace("grid:code", 'MGRS-', '') AS tile,
        ST_AsGeoJSON(ST_GeomFromWKB(geometry)) AS g,
        bbox.xmin, bbox.ymin, bbox.xmax, bbox.ymax,
        "proj:code", "proj:shape", "proj:transform",
        assets.planting."file:size", assets.harvest."file:size"
        FROM read_parquet('{PUB}/features/{year}/items.parquet')
        ORDER BY tile''' + (f" LIMIT {limit}" if limit else "")).fetchall()
    return [
        build_item(tile, year, _json.loads(g), [xmin, ymin, xmax, ymax], code, shape, transform,
                   sizes={"planting": ps, "harvest": hs})
        for tile, g, xmin, ymin, xmax, ymax, code, shape, transform, ps, hs in rows
    ]


def generate_items(year, workdir, limit=None, upload=True, workers=16,
                   from_parquet=False):
    """Per (tile, year): read COG header for proj, build item JSON, write to S3;
    accumulate a STAC-GeoParquet items.parquet and write it to S3. Outputs are
    NOT committed (the workdir should be gitignored).

    The two remote passes are pure network latency — ~1.3 s/tile serially, i.e.
    ~8 h for a year's 22.7k tiles — so both are parallelised: COG headers across
    *processes* (see _probe_proj), HEAD across threads. Run in-region (rails).

    ``from_parquet`` skips both passes and rebuilds the items from the published
    items.parquet — right for a metadata-only change, and runnable anywhere in a minute.
    """
    import json as _json
    d = Path(workdir) / "features" / str(year); d.mkdir(parents=True, exist_ok=True)
    places = load_places()
    if from_parquet:
        records = _records_from_published_parquet(year, limit)
        # A handful of assets came through the published parquet with no file:size (a HEAD
        # that failed on the original run). Only those get re-HEADed - tens, not ~45k.
        gaps = sorted({a["href"] for it in records for a in it["assets"].values()
                       if "file:size" not in a})
        if gaps:
            print(f"{year}: filling {len(gaps)} missing file:size via HEAD")
            with ThreadPoolExecutor(max_workers=workers) as pool:
                filled = dict(zip(gaps, pool.map(_head_size, gaps)))
            for it in records:
                for a in it["assets"].values():
                    if "file:size" not in a and filled.get(a["href"]) is not None:
                        a["file:size"] = filled[a["href"]]
        n_size = sum(1 for it in records for a in it["assets"].values() if "file:size" in a)
        n_missing = sum(1 for it in records for a in it["assets"].values() if "file:size" not in a)
        return _finish_items(d, year, records, places, n_size, n_missing, upload, workdir)
    import duckdb
    con = duckdb.connect()
    con.execute("INSTALL spatial; LOAD spatial; INSTALL httpfs; LOAD httpfs; SET TimeZone='UTC';")
    q = (f"SELECT tile_id, ST_AsGeoJSON(ANY_VALUE(geometry)) g, "
         f"ST_XMin(ANY_VALUE(geometry)) xmin, ST_YMin(ANY_VALUE(geometry)) ymin, "
         f"ST_XMax(ANY_VALUE(geometry)) xmax, ST_YMax(ANY_VALUE(geometry)) ymax "
         f"FROM read_parquet('{INDEX_PARQUET}') WHERE EXTRACT(year FROM time)={year} "
         f"GROUP BY tile_id ORDER BY tile_id" + (f" LIMIT {limit}" if limit else ""))
    rows = con.execute(q).fetchall()

    with ProcessPoolExecutor(max_workers=workers) as pool:
        proj = {r[0]: r[1:] for r in
                pool.map(_probe_proj, [(row[0], year) for row in rows], chunksize=8)
                if r is not None}
    records = []
    for tile_id, g, xmin, ymin, xmax, ymax in rows:
        if tile_id not in proj:
            continue
        proj_code, shape, transform = proj[tile_id]
        records.append(build_item(tile_id, year, _json.loads(g), [xmin, ymin, xmax, ymax],
                                  proj_code, shape, transform))
    # file:size via HTTP HEAD (cheap, parallel). file:checksum is deferred (see build_item).
    hrefs = sorted({a["href"] for it in records for a in it["assets"].values()})
    with ThreadPoolExecutor(max_workers=workers) as pool:
        sizes = dict(zip(hrefs, pool.map(_head_size, hrefs)))
    n_size = 0
    for it in records:
        for a in it["assets"].values():
            if sizes.get(a["href"]) is not None:
                a["file:size"] = sizes[a["href"]]; n_size += 1
    n_missing = sum(1 for h in hrefs if sizes.get(h) is None)
    return _finish_items(d, year, records, places, n_size, n_missing, upload, workdir)


def _finish_items(d, year, records, places, n_size, n_missing, upload, workdir):
    """Write the MGRS tree + grid catalogs + items.parquet, then upload the lot."""
    import json as _json
    by_gzd = {}
    for it in records:
        # Items live in the MGRS browse tree: features/<year>/<zone>/<gzd>/<iid>.json
        gzd = it["id"][:3]
        (d / gzd[:2] / gzd).mkdir(parents=True, exist_ok=True)
        (d / gzd[:2] / gzd / f"{it['id']}.json").write_text(_json.dumps(it))
        by_gzd.setdefault(gzd, []).append(it["id"])
    n_cat = _write_grid_catalogs(d, year, by_gzd, places)
    # STAC-GeoParquet (one row per item) via stac-geoparquet if available, else a simple parquet
    _write_stac_geoparquet(records, d / "items.parquet")
    print(f"{year}: wrote {len(records)} items ({n_size} asset file:size set, "
          f"{n_missing} unresolved; file:checksum deferred) + {n_cat} grid catalogs "
          f"+ items.parquet to {workdir}")
    if upload:
        base = f"s3://{S3_BUCKET}/{S3_PREFIX}/features/{year}"
        # Two passes so each gets the right Content-Type. The grid tree holds only
        # <iid>.json items and catalog.json nodes; items.parquet goes up separately.
        for include, ctype in ((f"*_{year}.json", "application/geo+json"),
                               ("*/catalog.json", "application/json")):
            subprocess.run(["aws", "s3", "cp", str(d), f"{base}/", "--recursive",
                            "--exclude", "*", "--include", include, "--quiet",
                            "--region", "us-west-2", "--content-type", ctype], check=True)
        subprocess.run(["aws", "s3", "cp", str(d / "items.parquet"),
                        f"{base}/items.parquet", "--quiet", "--region", "us-west-2"], check=True)
        print(f"{year}: uploaded the MGRS grid tree + items.parquet to {base}")
        print(f"NOTE: the pre-grid flat item prefix is now stale. After spot-checking the "
              f"new tree, remove it:\n  aws s3 rm {base}/items/ --recursive --region us-west-2")


def _write_grid_catalogs(d, year, by_gzd, places):
    """Write the zone + GZD catalog.json nodes over an already-written item tree."""
    counts = {g: len(v) for g, v in by_gzd.items()}
    by_zone = {}
    for gzd in sorted(by_gzd):
        by_zone.setdefault(gzd[:2], []).append(gzd)
    n = 0
    for zone, gzds in sorted(by_zone.items()):
        (d / zone / "catalog.json").write_text(
            json.dumps(build_zone_catalog(year, zone, gzds, counts, places), indent=2) + "\n")
        n += 1
        for gzd in gzds:
            (d / zone / gzd / "catalog.json").write_text(
                json.dumps(build_gzd_catalog(year, gzd, sorted(by_gzd[gzd]), places), indent=2) + "\n")
            n += 1
    return n


def _write_stac_geoparquet(items, path):
    try:
        import stac_geoparquet, pyarrow.parquet as pq
        rb = stac_geoparquet.arrow.parse_stac_items_to_arrow(items)
        pq.write_table(stac_geoparquet.arrow.stac_table_to_items and __import__("pyarrow").Table.from_batches(list(rb)) or rb, str(path))
    except Exception as e:  # noqa: BLE001
        # fallback: minimal columns so the index still exists
        print(f"WARNING: stac-geoparquet unavailable ({e}); writing a MINIMAL index parquet - "
              f"install stac-geoparquet and re-run before publishing {path}", file=sys.stderr)
        import pyarrow as pa, pyarrow.parquet as pq
        cols = {"id": [], "datetime": [], "bbox": [], "harvest_href": [], "planting_href": []}
        for it in items:
            cols["id"].append(it["id"]); cols["datetime"].append(it["properties"]["datetime"])
            cols["bbox"].append(json.dumps(it["bbox"]))
            cols["harvest_href"].append(it["assets"]["harvest"]["href"])
            cols["planting_href"].append(it["assets"]["planting"]["href"])
        pq.write_table(pa.table(cols), str(path))


def make_thumbnail(tile, year, workdir, upload=True):
    """Render a true-color (B04/B03/B02) preview of one tile's harvest composite to
    features/thumbnail.png (the collection thumbnail)."""
    import numpy as np
    import rasterio
    from rasterio.enums import Resampling
    from PIL import Image
    Path(workdir).mkdir(parents=True, exist_ok=True)
    out = Path(workdir) / "thumbnail.png"
    cog = f"{COG_BASE}/s2med_harvest/{tile}/{year}0101.tif"
    target = 600
    with rasterio.open(cog) as ds:
        scale = max(1, ds.width // target)
        w, h = ds.width // scale, ds.height // scale
        rgb = ds.read([3, 2, 1], out_shape=(3, h, w),
                      resampling=Resampling.average).astype("float32")  # R=B04, G=B03, B=B02
    arr = np.zeros((h, w, 3), dtype="uint8")
    for i in range(3):
        b = rgb[i]
        v = b[np.isfinite(b) & (b > 0)]
        if v.size:
            lo, hi = np.percentile(v, [2, 98])
            arr[..., i] = (np.clip((np.nan_to_num(b) - lo) / (hi - lo + 1e-6), 0, 1) * 255).astype("uint8")
    Image.fromarray(arr).save(out)
    print(f"wrote {out} ({w}x{h}) from harvest tile {tile} {year}")
    if upload:
        subprocess.run(["aws", "s3", "cp", str(out),
                        f"s3://{S3_BUCKET}/{S3_PREFIX}/features/thumbnail.png",
                        "--quiet", "--region", "us-west-2", "--content-type", "image/png"], check=True)
        print("uploaded features/thumbnail.png")


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__)
    sub = ap.add_subparsers(dest="cmd", required=True)
    c = sub.add_parser("collections"); c.add_argument(
        "--out", default=str(Path(__file__).resolve().parents[2] / "catalog"))
    it = sub.add_parser("items"); it.add_argument("year", type=int, choices=[2024, 2025])
    it.add_argument("--workdir", default=os.environ.get("WORK", "/tmp/ftw-features"))
    it.add_argument("--limit", type=int, default=None)
    it.add_argument("--workers", type=int, default=16,
                    help="parallel remote reads (COG header + HEAD); network-bound")
    it.add_argument("--no-upload", action="store_true")
    it.add_argument("--from-parquet", action="store_true",
                    help="rebuild items from the published items.parquet instead of re-reading "
                         "COG headers + HEADing assets (metadata-only changes; runs anywhere)")
    th = sub.add_parser("thumbnail"); th.add_argument("--tile", default="31UDP")
    th.add_argument("--year", type=int, default=2024)
    th.add_argument("--workdir", default=os.environ.get("WORK", "/tmp/ftw-features"))
    th.add_argument("--no-upload", action="store_true")
    pl = sub.add_parser("places", help="rebuild mgrs_places.json (duckdb+spatial, network)")
    pl.add_argument("--workdir", default=os.environ.get("WORK", "/tmp/ftw-features"))
    args = ap.parse_args(argv)
    if args.cmd == "collections":
        write_collections(args.out)
    elif args.cmd == "places":
        build_places(args.workdir)
    elif args.cmd == "thumbnail":
        make_thumbnail(args.tile, args.year, args.workdir, upload=not args.no_upload)
    else:
        generate_items(args.year, args.workdir, args.limit, upload=not args.no_upload,
                       workers=args.workers, from_parquet=args.from_parquet)
    return 0


if __name__ == "__main__":
    sys.exit(main())
